INSERT INTO dbo.Projects (ProjectId, Name, Description, Status, StartDate, EndDate, Budget, Color) VALUES
  (1, N'Customer Self-Service Portal', N'A web portal where customers can view orders, download invoices and raise support tickets without calling the help desk.', N'Active', DATEADD(day, -45, @Today), DATEADD(day, 60, @Today), 185000, '#4F46E5'),
  (2, N'Field Technician Mobile App', N'Offline-first mobile app that gives field technicians their daily job list, parts inventory and photo-based sign-off.', N'Active', DATEADD(day, -20, @Today), DATEADD(day, 90, @Today), 240000, '#0891B2'),
  (3, N'Data Warehouse Modernization', N'Move nightly reporting from on-prem SSIS jobs to Azure Data Factory and a dimensional model in Azure SQL.', N'Active', DATEADD(day, -70, @Today), DATEADD(day, 30, @Today), 130000, '#059669'),
  (4, N'Zero Trust Security Rollout', N'Enforce Entra ID conditional access, MFA and least-privilege roles across all internal line-of-business apps.', N'OnHold', DATEADD(day, -10, @Today), DATEADD(day, 120, @Today), 95000, '#DC2626'),
  (5, N'Marketing Website Redesign', N'Refresh brand, rebuild the public website for speed and accessibility (WCAG 2.2 AA), and move content to a headless CMS.', N'Completed', DATEADD(day, -120, @Today), DATEADD(day, -15, @Today), 72000, '#D97706'),
  (6, N'AI Support Assistant Pilot', N'Pilot an AI assistant that drafts answers to support tickets from the knowledge base, with human review before sending.', N'Planned', DATEADD(day, 25, @Today), DATEADD(day, 110, @Today), 60000, '#9333EA');
INSERT INTO dbo.Tasks (TaskId, ProjectId, Title, Description, Status, Priority, EstimatedHours, DueDate) VALUES
  (1, 1, N'Gather portal requirements', N'Interview support leads and 5 key customers; produce prioritized user stories.', N'Done', N'High', 24, DATEADD(day, -35, @Today)),
  (2, 1, N'Design portal wireframes', N'Low-fidelity wireframes for dashboard, orders, invoices and tickets; mobile first.', N'Done', N'High', 32, DATEADD(day, -25, @Today)),
  (3, 1, N'Set up Entra ID sign-in', N'Customer sign-in with Entra External ID, token validation in the API.', N'Done', N'Critical', 20, DATEADD(day, -12, @Today)),
  (4, 1, N'Build orders API', N'REST endpoints for order list and order detail with paging and filtering.', N'InProgress', N'High', 40, DATEADD(day, 5, @Today)),
  (5, 1, N'Invoice PDF download', N'Generate and stream invoice PDFs from the billing system; cache in Blob Storage.', N'InProgress', N'Medium', 28, DATEADD(day, 12, @Today)),
  (6, 1, N'Support ticket form', N'Form with attachments that creates tickets in the help desk system.', N'Todo', N'Medium', 24, DATEADD(day, 20, @Today)),
  (7, 1, N'Responsive dashboard UI', N'Implement dashboard cards and order table that adapt from phone to desktop.', N'InProgress', N'High', 36, DATEADD(day, 8, @Today)),
  (8, 1, N'Portal end-to-end tests', N'Playwright tests for sign-in, orders and invoices across three browsers.', N'Todo', N'Medium', 30, DATEADD(day, 35, @Today)),
  (9, 1, N'Customer help articles', N'Write 10 short how-to articles linked from the portal.', N'Todo', N'Low', 16, DATEADD(day, 50, @Today)),
  (10, 2, N'Technician journey mapping', N'Ride along with two technicians and map their day, pain points and offline gaps.', N'Done', N'High', 16, DATEADD(day, -12, @Today)),
  (11, 2, N'Offline sync design', N'Choose sync strategy and conflict rules for jobs, parts and photos.', N'InProgress', N'Critical', 24, DATEADD(day, 4, @Today)),
  (12, 2, N'Job list screen', N'Daily job list with map view, status chips and pull-to-refresh.', N'InProgress', N'High', 32, DATEADD(day, 14, @Today)),
  (13, 2, N'Photo sign-off capture', N'Capture photos and customer signature; upload when connectivity returns.', N'Todo', N'High', 30, DATEADD(day, 28, @Today)),
  (14, 2, N'Parts inventory API', N'Expose van stock levels and reservations from the ERP.', N'Blocked', N'Medium', 26, DATEADD(day, 18, @Today)),
  (15, 2, N'Mobile CI pipeline', N'Build, sign and distribute test builds from GitHub Actions.', N'Todo', N'Medium', 18, DATEADD(day, 22, @Today)),
  (16, 2, N'Pilot with 10 technicians', N'Run a two-week pilot and collect feedback.', N'Todo', N'High', 40, DATEADD(day, 70, @Today)),
  (17, 3, N'Inventory existing SSIS jobs', N'List all packages, schedules, sources and downstream reports.', N'Done', N'High', 20, DATEADD(day, -60, @Today)),
  (18, 3, N'Design star schema', N'Sales, inventory and service fact tables with conformed dimensions.', N'Done', N'Critical', 36, DATEADD(day, -40, @Today)),
  (19, 3, N'Build ADF pipelines', N'Incremental loads with watermarking and retry policies.', N'InProgress', N'High', 60, DATEADD(day, 3, @Today)),
  (20, 3, N'Reconcile report totals', N'Compare old and new reports for 3 months of history; explain differences.', N'InProgress', N'High', 24, DATEADD(day, 10, @Today)),
  (21, 3, N'Decommission on-prem jobs', N'Turn off SSIS schedules after sign-off; archive packages.', N'Todo', N'Medium', 8, DATEADD(day, 28, @Today)),
  (22, 3, N'Data dictionary', N'Document every table and measure for report authors.', N'Todo', N'Low', 14, DATEADD(day, 25, @Today)),
  (23, 4, N'App access audit', N'Review who can access each internal app and why.', N'Done', N'High', 18, DATEADD(day, -4, @Today)),
  (24, 4, N'Conditional access policies', N'Draft policies for MFA, device compliance and risky sign-ins.', N'Blocked', N'Critical', 22, DATEADD(day, 15, @Today)),
  (25, 4, N'Role-based access model', N'Define app roles and groups for each line-of-business app.', N'Todo', N'High', 16, DATEADD(day, 30, @Today)),
  (26, 4, N'Staff MFA guide', N'Plain-language guide and FAQ for staff enrolling in MFA.', N'Todo', N'Medium', 10, DATEADD(day, 40, @Today)),
  (27, 5, N'Brand refresh', N'New palette, typography and component library.', N'Done', N'High', 40, DATEADD(day, -95, @Today)),
  (28, 5, N'Headless CMS migration', N'Move 180 pages to the headless CMS with redirects.', N'Done', N'High', 50, DATEADD(day, -60, @Today)),
  (29, 5, N'Accessibility audit', N'WCAG 2.2 AA audit and fixes for all templates.', N'Done', N'Critical', 24, DATEADD(day, -35, @Today)),
  (30, 5, N'Go-live and monitoring', N'DNS cut-over, CDN rules, uptime and Core Web Vitals monitoring.', N'Done', N'High', 12, DATEADD(day, -16, @Today)),
  (31, 6, N'Define pilot success metrics', N'Agree on accuracy, handling-time and satisfaction targets.', N'Todo', N'High', 8, DATEADD(day, 30, @Today)),
  (32, 6, N'Knowledge base clean-up', N'Remove outdated articles and tag the rest by product.', N'Todo', N'Medium', 20, DATEADD(day, 45, @Today)),
  (33, 6, N'Prototype answer drafting', N'Prototype retrieval + drafting against 200 historical tickets.', N'Todo', N'High', 40, DATEADD(day, 65, @Today)),
  (34, 6, N'Responsible AI review', N'Privacy, safety and human-in-the-loop review before pilot.', N'Todo', N'Critical', 12, DATEADD(day, 80, @Today));
